import chromadb

def get_collection(directory: str = "./chroma_db", name: str = "collection_1"):
    client = chromadb.PersistentClient(path=directory)
    return client.get_or_create_collection(name=name)


def store_reports(
        texts : list[str], 
        embeddings: list, 
        meta_data : list[dict],
        directory: str = "./chroma_db"
):
    collection = get_collection(directory)
    collection.add(
        documents = texts,
        embeddings = embeddings,
        metadatas = meta_data,
        ids=[str(i) for i in range(len(texts))]  # unique IDs for chromadb
    )

def search_reports(query_embedding: list, directory: str = "./chroma_db") -> list[dict]:
    collection = get_collection(directory)
    results = collection.query(
        query_embeddings=[query_embedding],
        n_results=3  # return top 3 most similar reports
    )
    return results

